import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';

const PAGE_SIZE = 5;

const statusMap = {
  'Active': 'Đang làm việc',
  'Intern': 'Thực tập sinh',
  'Probation': 'Thử việc',
  'On Leave': 'Nghỉ phép',
  'Terminated': 'Đã nghỉ việc'
};

const statusColors = {
  'Active': '#10b981',
  'Intern': '#3b82f6',
  'Probation': '#f59e0b',
  'On Leave': '#ef4444',
  'Terminated': '#64748b'
};

export default function ReportsAttendance(props) {
  const navigate = useNavigate();
  const { reportRows, summary, reportMeta, selectedMonth, availableMonths, onMonthChange, onBack } = props;
  const [selectedDept, setSelectedDept] = useState('ALL');
  const [currentPage, setCurrentPage] = useState(1);

  const filteredRows = useMemo(() => {
    return selectedDept === 'ALL' 
      ? reportRows 
      : reportRows.filter(r => r.DepartmentName === selectedDept);
  }, [reportRows, selectedDept]);

  const stats = useMemo(() => {
    const absent = filteredRows.reduce((sum, r) => sum + (Number(r.AbsentDays) || 0), 0);
    const leave = filteredRows.reduce((sum, r) => sum + (Number(r.LeaveDays) || 0), 0);
    return { absent, leave, total: absent + leave };
  }, [filteredRows]);

  const chartData = useMemo(() => {
    const labels = ['Thứ 2', 'Thứ 3', 'Thứ 4', 'Thứ 5', 'Thứ 6', 'Thứ 7', 'CN'];
    const values = reportMeta?.weekdayStats || [0, 0, 0, 0, 0, 0, 0];
    return labels.map((l, i) => ({ name: l, value: values[i] }));
  }, [reportMeta]);

  const pagedRows = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredRows.slice(start, start + PAGE_SIZE);
  }, [filteredRows, currentPage]);

  const totalPages = Math.ceil(filteredRows.length / PAGE_SIZE);

  return (
    <div className="premium-report-wrapper" style={{ padding: '30px', background: '#f0f2f5', minHeight: '100vh', fontFamily: "'Outfit', 'Inter', sans-serif" }}>

      {/* Top Header Section */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '32px' }}>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', color: '#3b82f6', fontWeight: '600', cursor: 'pointer', marginBottom: '12px' }} onClick={onBack}>
            <span style={{ fontSize: '20px' }}>←</span> Quay lại Dashboard
          </div>
          <h1 style={{ margin: 0, fontSize: '32px', fontWeight: '800', color: '#1e293b', letterSpacing: '-0.5px' }}>
            Báo cáo Chuyên sâu <span style={{ color: '#3b82f6' }}>{selectedMonth?.split('-')[1]}/{selectedMonth?.split('-')[0]}</span>
          </h1>
        </div>
        <div style={{ display: 'flex', gap: '15px' }}>
          <div className="premium-select-wrapper">
            <select 
              value={selectedMonth} 
              onChange={(e) => onMonthChange(e.target.value)}
              className="premium-select"
            >
              {availableMonths.map(m => <option key={m.value} value={m.value}>{m.label}</option>)}
            </select>
          </div>
          <button className="premium-btn-primary" onClick={() => window.print()}>
            <span style={{ marginRight: '8px' }}>📥</span> Xuất File PDF
          </button>
        </div>
      </div>

      {/* Hero Statistics Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '24px', marginBottom: '32px' }}>
        {[
          { label: 'Nhân sự', value: summary.totalEmployees, icon: '👥', gradient: 'linear-gradient(135deg, #6366f1 0%, #4f46e5 100%)' },
          { label: 'Đi làm', value: summary.presentEmployees, icon: '✨', gradient: 'linear-gradient(135deg, #10b981 0%, #059669 100%)' },
          { label: 'Vắng mặt', value: summary.absentEmployees, icon: '🛑', gradient: 'linear-gradient(135deg, #f43f5e 0%, #e11d48 100%)' },
          { label: 'Nghỉ phép', value: summary.lateLeaveEmployees, icon: '🏖️', gradient: 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)' }
        ].map((item, idx) => (
          <div key={idx} className="premium-stat-card" style={{ background: item.gradient }}>
            <div className="stat-icon">{item.icon}</div>
            <div className="stat-content">
              <span className="stat-label">{item.label}</span>
              <span className="stat-value">{item.value}</span>
            </div>
            <div className="stat-decoration"></div>
          </div>
        ))}
      </div>

      {/* Main Charts Area */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.8fr 1.2fr', gap: '30px', marginBottom: '32px' }}>
        <div className="premium-card chart-card">
          <div className="card-header">
            <h3>Phân tích xu hướng đi làm</h3>
            <div className="badge-blue">Dữ liệu thực tế</div>
          </div>
          <div style={{ width: '100%', height: 320 }}>
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 13, fontWeight: 500}} dy={15} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#94a3b8', fontSize: 13, fontWeight: 500}} dx={-10} />
                <Tooltip 
                  contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', padding: '12px' }}
                />
                <Area type="monotone" dataKey="value" stroke="#6366f1" strokeWidth={4} fillOpacity={1} fill="url(#areaGradient)" dot={{ r: 6, fill: '#6366f1', strokeWidth: 3, stroke: '#fff' }} activeDot={{ r: 8, strokeWidth: 0 }} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="premium-card pie-card">
          <div className="card-header">
            <h3>Tỷ lệ nghỉ phép</h3>
          </div>
          <div style={{ width: '100%', height: 260, position: 'relative' }}>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={[
                    { name: 'Nghỉ phép', value: stats.leave },
                    { name: 'Vắng mặt', value: stats.absent }
                  ]} 
                  innerRadius={70} 
                  outerRadius={95} 
                  paddingAngle={8} 
                  dataKey="value"
                  stroke="none"
                >
                  <Cell fill="#10b981" />
                  <Cell fill="#f43f5e" />
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="pie-center-text">
              <span className="total-val">{stats.total}</span>
              <span className="total-desc">Ngày nghỉ</span>
            </div>
          </div>
          <div className="pie-legend-premium">
            <div className="legend-row">
              <div className="legend-name"><span className="dot-green"></span> Nghỉ phép</div>
              <div className="legend-val">{stats.leave} ngày</div>
            </div>
            <div className="legend-row">
              <div className="legend-name"><span className="dot-red"></span> Vắng mặt</div>
              <div className="legend-val">{stats.absent} ngày</div>
            </div>
          </div>
        </div>
      </div>

      {/* Advanced Data Table */}
      <div className="premium-card table-card">
        <div className="table-header-premium">
          <div className="header-left">
            <h3>Danh sách chi tiết nhân viên</h3>
            <p>Hiển thị kết quả lọc theo phòng ban và tháng</p>
          </div>
          <div className="header-right">
            <select 
              className="premium-filter-select"
              value={selectedDept} 
              onChange={(e) => { setSelectedDept(e.target.value); setCurrentPage(1); }}
            >
              <option value="ALL">Tất cả phòng ban</option>
              {props.departmentOptions.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>

        <div className="premium-table-container">
          <table className="premium-table">
            <thead>
              <tr>
                <th>THÔNG TIN NHÂN VIÊN</th>
